--
-- Name: collections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.collections (
    do_no text NOT NULL,
    source text DEFAULT 'live'::text NOT NULL,
    job_no text,
    do_date date,
    do_type text,
    trip_type text,
    site_id text,
    vessel_name text,
    berth text,
    vehicle_id text,
    driver_id text,
    job_type text,
    waste_type text,
    bin_in text,
    bin_out text,
    vol_cat_a numeric(8,2),
    vol_cat_b numeric(8,2),
    vol_cat_c numeric(8,2),
    vol_cat_d numeric(8,2),
    vol_cat_e numeric(8,2),
    vol_cat_f numeric(8,2),
    vol_total_m3 numeric(8,2),
    gross_kg numeric(10,1),
    tare_kg numeric(10,1),
    net_kg numeric(10,1),
    weigh_ticket_no text,
    weigh_location text,
    weight_source text DEFAULT 'volume_est'::text,
    gps_lat numeric(9,6),
    gps_lng numeric(9,6),
    gps_accuracy_m numeric(6,1),
    gps_captured_at timestamp with time zone,
    photo_do_ref text,
    photo_sig_ref text,
    photo_weigh_ref text,
    receipt_ref text,
    disposal_facility text,
    xero_invoice_id text,
    backfill_notes text,
    synced_at timestamp with time zone DEFAULT now() NOT NULL,
    sludge_requested_t numeric,
    sludge_actual_t numeric,
    dispose_to text,
    vol_cat_i numeric,
    vol_other_m3 numeric,
    other_desc text,
    vol_oily_rags_m3 numeric,
    vol_expired_med_m3 numeric,
    bin_qty integer,
    voyage_no text,
    claim_state text DEFAULT 'UNASSIGNED'::text,
    CONSTRAINT collections_claim_state_check CHECK ((claim_state = ANY (ARRAY['UNASSIGNED'::text, 'INSET'::text, 'CREDIT'::text]))),
    CONSTRAINT collections_source_check CHECK ((source = ANY (ARRAY['live'::text, 'backfill'::text]))),
    CONSTRAINT collections_weight_source_check CHECK ((weight_source = ANY (ARRAY['weighbridge'::text, 'volume_est'::text, 'invoice'::text])))
);


--
-- Name: COLUMN collections.sludge_requested_t; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.collections.sludge_requested_t IS 'Sludge requested (tonnes), MARPOL Annex I. Nullable; home for the PIL invoice backfill. NULL/0 until backfilled.';


--
-- Name: COLUMN collections.sludge_actual_t; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.collections.sludge_actual_t IS 'Sludge actually recovered (tonnes). Nullable; feeds recovery/avoided in the report function. NULL/0 until backfilled.';


--
-- Name: COLUMN collections.vol_oily_rags_m3; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.collections.vol_oily_rags_m3 IS 'Oily rags m3 captured on the vessel DO (was Remarks-only before 8 Aug 2026)';


--
-- Name: COLUMN collections.vol_expired_med_m3; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.collections.vol_expired_med_m3 IS 'Expired medicine m3 captured on the vessel DO (was Remarks-only before 8 Aug 2026)';


--
-- Name: COLUMN collections.bin_qty; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.collections.bin_qty IS '660L job type only: number of 660L bins handled at the site. Trip charge = unit price x bin_qty. Added 11 Aug 2026 (Michelle).';


--
-- Name: COLUMN collections.voyage_no; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.collections.voyage_no IS 'Vessel voyage number; backfilled 13 Aug 2026 from PIL monthly management reports (May+June); capture going forward at OCR/app';


--
-- Name: COLUMN collections.claim_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.collections.claim_state IS 'Who owns the emissions-reduction claim for this load: INSET = assigned to the client as their Scope 3 Cat 5 reduction; CREDIT = retained by Lirich for potential carbon-credit issuance; UNASSIGNED = default until set BY CONTRACT. One claim per tonne, never both - transitions must be audited. Decision framework: Lirich_Carbon_Blockchain_Plan.md. Default proposal pending Qris+Michelle: INSET for client-service streams, CREDIT only for Lirich-yard-created recovery gains. Column added 21 Aug 2026; no rows assigned yet.';


--
-- Name: collections_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.collections_effective AS
 SELECT do_no,
    source,
    job_no,
    do_date,
    do_type,
    trip_type,
    site_id,
    vessel_name,
    berth,
    vehicle_id,
    driver_id,
    job_type,
    waste_type,
    bin_in,
    bin_out,
    vol_cat_a,
    vol_cat_b,
    vol_cat_c,
    vol_cat_d,
    vol_cat_e,
    vol_cat_f,
    vol_total_m3,
    gross_kg,
    tare_kg,
    net_kg,
    weigh_ticket_no,
    weigh_location,
    weight_source,
    gps_lat,
    gps_lng,
    gps_accuracy_m,
    gps_captured_at,
    photo_do_ref,
    photo_sig_ref,
    photo_weigh_ref,
    receipt_ref,
    disposal_facility,
    xero_invoice_id,
    backfill_notes,
    synced_at,
    COALESCE(( SELECT (a.new_value)::numeric AS new_value
           FROM public.adjustments a
          WHERE ((a.do_no = c.do_no) AND (a.field = 'net_kg'::text))
          ORDER BY a.adjusted_at DESC
         LIMIT 1), net_kg) AS net_kg_effective,
    COALESCE(( SELECT (a.new_value)::numeric AS new_value
           FROM public.adjustments a
          WHERE ((a.do_no = c.do_no) AND (a.field = 'vol_total_m3'::text))
          ORDER BY a.adjusted_at DESC
         LIMIT 1), vol_total_m3) AS vol_total_m3_effective
   FROM public.collections c;


