--
-- Name: v_dump_fairness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dump_fairness AS
 WITH base AS (
         SELECT COALESCE(( SELECT (fleet_settings.value)::date AS value
                   FROM public.fleet_settings
                  WHERE (fleet_settings.key = 'fairness_baseline_date'::text)), '2026-09-01'::date) AS baseline
        ), counted AS (
         SELECT d.driver_id,
            d.name,
            count(j.order_no) FILTER (WHERE ((j.category = 'dump'::text) AND (j.status = ANY (ARRAY['assigned'::text, 'accepted'::text, 'in_progress'::text, 'done'::text])) AND (j.service_date >= ( SELECT base.baseline
                   FROM base)))) AS dump_trips,
            count(j.order_no) FILTER (WHERE ((j.category = 'rotation'::text) AND (j.status = ANY (ARRAY['assigned'::text, 'accepted'::text, 'in_progress'::text, 'done'::text])) AND (j.service_date >= ( SELECT base.baseline
                   FROM base)))) AS vessel_jobs
           FROM (public.drivers d
             LEFT JOIN public.job_orders j ON ((j.driver_id = d.driver_id)))
          WHERE d.active
          GROUP BY d.driver_id, d.name
        ), avail AS (
         SELECT c_1.driver_id,
            GREATEST((((CURRENT_DATE - ( SELECT base.baseline
                   FROM base)) + 1) - COALESCE(( SELECT sum(((LEAST(a_1.date_to, CURRENT_DATE) - GREATEST(a_1.date_from, ( SELECT base.baseline
                           FROM base))) + 1)) AS sum
                   FROM public.driver_availability a_1
                  WHERE ((a_1.driver_id = c_1.driver_id) AND a_1.active AND (a_1.date_to >= ( SELECT base.baseline
                           FROM base)) AND (a_1.date_from <= CURRENT_DATE))), (0)::bigint)), (1)::bigint) AS available_days
           FROM counted c_1
        )
 SELECT c.driver_id,
    c.name,
    c.dump_trips,
    c.vessel_jobs,
    a.available_days,
    round(((c.dump_trips)::numeric / (NULLIF(a.available_days, 0))::numeric), 3) AS trips_per_avail_day,
    (c.dump_trips - min(c.dump_trips) OVER ()) AS handicap,
    ( SELECT base.baseline
           FROM base) AS baseline_date
   FROM (counted c
     JOIN avail a USING (driver_id));


